  "textCompare": [
   {
    "source": "Textul Masoretic (ebraică)",
    "original": "וַיְמַהֵר אַבְרָהָם הָאֹהֱלָה אֶל־שָׂרָה וַיֹּאמֶר מַהֲרִי שְׁלֹשׁ סְאִים קֶמַח סֹלֶת לוּשִׁי וַעֲשִׂי עֻגוֹת",
    "translation": "„Avraham s-a grăbit către cort, la Sara, și a spus: „Grăbește-te! [Ia] trei măsuri de făină [și trei de] făină fină ! Frământă și fă turte!”” — traducerea rabinului Rosen.",
    "note": ""
   },
   {
    "source": "Septuaginta (greacă)",
    "original": "καὶ ἔσπευσεν Αβρααμ ἐπὶ τὴν σκηνὴν πρὸς Σαρραν καὶ εἶπεν αὐτῇ Σπεῦσον καὶ φύρασον τρία μέτρα σεμιδάλεως καὶ ποίησον ἐγκρυφίας.",
    "greek": true,
    "translation": "",
    "note": ""
   },
   {
    "source": "Pentateuhul Samaritean",
    "original": "וימהר אברהם האהלה אל שרה ויאמר מהרי שלש סים קמח סלת לושי ועשה עגות",
    "translation": "Diferență reală, confirmată: וימהר אברהם האהלה אל שרה ויאמר מהרי שלש סים קמח סלת לושי ועשה עגות — „Avraham s-a grăbit către cort, la Sara, și a spus: „Grăbește-te! [Ia] trei măsuri de făină [și trei de] făină fină ! Frământă și fă turte!”",
    "note": "(Sursă: Schorch, ed. critică 2018, ms. Chester Beatty 751)."
   }
  ],
  "fidela": "Și Avraam s-a grăbit în cort la Sara și a spus: Grăbește-te, pregătește repede trei măsuri de făină fină, frământă și fă turte pe vatră.",
  "refs": [
   "Geneza 19:3"
  ],
  "commentaries": [
   {
    "author": "Rashi (1040–1105)",
    "text": "«Făină (qemaḥ)… făină fină (solet).» Făina fină pentru turte; făina de rând pentru coca bucătarilor, ca să acopere oala, ca să absoarbă spuma."
   },
   {
    "author": "Ibn Ezra (1089–1167)",
    "text": "«Frământă (luši).» Ca „și a frământat (wa-tlaš)”."
   },
   {
    "author": "Ramban / Nahmanide (1194–1270)",
    "text": "«făină și trei de făină fină» „Făină fină – pentru turte; făină – pentru aluatul bucătarilor, ca să acopere oala, ca să tragă spuma” – cuvintele lui Rashi. Și așa este în Bereșit Rabba; și acolo au explicat că erau trei măsuri pentru fiecare; și nu știm de ce a înmulțit atât de mult pâinea pentru trei oameni. Poate a știut de înălțarea mâncării, fiecare pe rând, și este ca cel care înmulțește arderile de tot pe altar; sau au mâncat cu ei, pentru cinstea lor, cei mari ai casei lui. Iar pe calea sensului simplu: „Grăbește-te! Ia trei măsuri de făină”, ca să faci din ele făină fină; și iată, a scos din toate cele trei măsuri puțină făină fină curată."
   },
   {
    "author": "Rashbam (cca. 1085–1158)",
    "text": "«Făină, făină fină (qemaḥ solet).» Făină de grâu; căci oriunde este scris solet este din grâu, cum învățăm de la învestire (milluʾim), unde este scris: „din făină fină de grâu să le faci”."
   },
   {
    "author": "Radak (cca. 1160–1235)",
    "text": "«Trei măsuri»: ca să facă turte de pâine dintr-o măsură pentru fiecare, pe calea cinstei.<br><br>«Făină și ... făină fină» (qemaḥ solet): făină din care să se facă făină fină pentru turte, pentru că sunt pâine subțire, ca să se coacă repede."
   }
  ]
